import{_ as i,I as s,c as n,o,j as a,J as d,ag as l,a as t}from"./chunks/framework.ARG558ZT.js";const v=JSON.parse('{"title":"S3 uploads and event-driven imports","description":"","frontmatter":{},"headers":[],"relativePath":"aws/file-imports.md","filePath":"aws/file-imports.md"}'),p={name:"aws/file-imports.md"};function c(u,e,h,m,f,b){const r=s("MermaidDiagram");return o(),n("div",null,[e[0]||(e[0]=a("h1",{id:"s3-uploads-and-event-driven-imports",tabindex:"-1"},[t("S3 uploads and event-driven imports "),a("a",{class:"header-anchor",href:"#s3-uploads-and-event-driven-imports","aria-label":"Permalink to “S3 uploads and event-driven imports”"},"​")],-1)),e[1]||(e[1]=a("p",null,"File transfer and file processing are separate operations. A browser can finish uploading a CSV before its records have been validated and persisted.",-1)),e[2]||(e[2]=a("h2",{id:"presigned-upload-flow",tabindex:"-1"},[t("Presigned upload flow "),a("a",{class:"header-anchor",href:"#presigned-upload-flow","aria-label":"Permalink to “Presigned upload flow”"},"​")],-1)),d(r,{"encoded-source":"sequenceDiagram%0A%20%20%20%20participant%20B%20as%20Browser%0A%20%20%20%20participant%20A%20as%20Authorized%20API%0A%20%20%20%20participant%20S%20as%20S3%0A%20%20%20%20participant%20P%20as%20Import%20parser%0A%20%20%20%20B-%3E%3EA%3A%20Request%20upload%20permission%0A%20%20%20%20A-%3E%3EA%3A%20Authorize%20user%20and%20select%20object%20key%0A%20%20%20%20A--%3E%3EB%3A%20Short-lived%20presigned%20upload%20URL%0A%20%20%20%20B-%3E%3ES%3A%20Upload%20object%20with%20signed%20request%0A%20%20%20%20S--%3E%3EP%3A%20Object-created%20event%0A%20%20%20%20P-%3E%3ES%3A%20Read%20and%20validate%20file"}),e[3]||(e[3]=l('<p>A presigned URL authorizes a particular request using the signer&#39;s permissions. It is a bearer capability: someone who obtains it may use it while valid. Do not put it into public logs. Choose keys on the server so a caller cannot overwrite arbitrary objects, and define constraints suitable for the chosen upload mechanism. <a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/PresignedUrlUploadObject.html" target="_blank" rel="noreferrer">Presigned uploads</a>.</p><p>The API does not need to relay every file byte through Lambda. Browser-to-S3 upload avoids turning the API into a file-transfer bottleneck, while the API still controls who obtains upload permission.</p><h2 id="object-events-need-a-deliberate-boundary" tabindex="-1">Object events need a deliberate boundary <a class="header-anchor" href="#object-events-need-a-deliberate-boundary" aria-label="Permalink to “Object events need a deliberate boundary”">​</a></h2><p>An S3 event identifies objects; it is not the full file body. Decode the event key correctly and fetch the intended object. Event delivery can repeat and ordering is not universal. Track a stable import identity and, where needed, object version to distinguish duplicate delivery from a genuinely new upload. <a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/EventNotifications.html" target="_blank" rel="noreferrer">S3 event notifications</a>.</p><p>Separate input and output prefixes, such as <code>incoming/</code> and <code>processed/</code>. A handler that writes into its own triggering prefix can produce a processing loop. Filters reduce accidental triggers, but application logic must still validate the event.</p><h2 id="csv-is-structured-input" tabindex="-1">CSV is structured input <a class="header-anchor" href="#csv-is-structured-input" aria-label="Permalink to “CSV is structured input”">​</a></h2><p>Splitting on commas does not handle quoted fields, escaped quotes or embedded newlines. Use a parser with explicit delimiter, header and encoding rules. Streaming can reduce memory consumption, but it still needs bounded file size, row size and downstream concurrency.</p><p>Convert strings explicitly. Decide whether an empty description is valid, whether a price must be positive, and whether zero stock is allowed. Rejecting a row should not silently turn it into a partially valid record.</p><p>The parser can submit individual validated row messages to SQS. Batching can reduce API overhead, but each batch API response must be checked for individual failures. Record progress so retrying a file does not blindly recreate every successful product.</p><h2 id="completion-and-failure-are-business-states" tabindex="-1">Completion and failure are business states <a class="header-anchor" href="#completion-and-failure-are-business-states" aria-label="Permalink to “Completion and failure are business states”">​</a></h2><p>A useful import lifecycle distinguishes accepted, uploaded, processing, completed, partially failed and failed. “Upload succeeded” is a file-transfer statement; “import completed” is a business-processing statement.</p><p>Keep enough information to connect the user request, file, import, row and created record. Do not expose raw file contents or sensitive rows in general logs. If the worker persists records and publishes notifications, plan for failure between those operations; an outbox or equivalent recovery mechanism may be needed.</p><p>Continue with <a href="./messaging.html">SQS and SNS</a> for the consumer&#39;s failure contract.</p>',13))])}const A=i(p,[["render",c]]);export{v as __pageData,A as default};
